<script>

export default {
  props: ['params'],
  data() {
    return {
      project: null,
    }
  },
  async created() {
    this.project = this.$projects.allProjectsById[this.projectId]
  },
  computed: {
    // Dockview hands the panel params either nested (`params.params`) or flat
    // depending on how the panel was created — normalise both shapes here.
    panelParams() {
      return this.params?.params || this.params || {}
    },
    chat() {
      const chatId = this.panelParams?.chat?.id
      return this.$storex.chats.chats[chatId]
    },
    // Workspace panels carry the raw workspace (name, path, …) in params under
    // the `workspace` key; fall back to the legacy `app` slot for old payloads.
    workspace() {
      return this.panelParams?.workspace || this.panelParams?.app
    },
    app() {
      return this.panelParams?.app
    },
    // Board-scoped panels (multiple task managers) carry a `boardId`.
    board() {
      const boardId = this.panelParams?.boardId
      return boardId ? this.$storex.kanban.boardById(boardId) : null
    },
    // Icon source: the app, the workspace, or a synthetic entry for board-scoped
    // panels (which have no app of their own) so tabs stay distinguishable.
    tabApp() {
      return this.app || this.workspace || (this.board
        ? { icon: 'fa-solid fa-layer-group', title: this.board.title }
        : null)
    },
    tabName() {
      return this.chat?.name ||
        this.workspace?.name ||
        this.workspace?.title ||
        this.board?.title ||
        this.app?.title ||
        this.panelParams?.tabName
    },
    api() {
      return this.params.api
    },
    containerApi() {
      return this.params.containerApi
    },
    panel() {
      return this.api.panel
    },
    projectId() {
      return this.panelParams?.project_id
    },
    isUpdating() {
      return this.$storex.chats.isChatUpdating(this.chat?.id)
    }
  },
  methods: {
    onDragStart(event) {
      // Only register a sprint task id when the tab is backed by a chat
      if (!this.chat) return
      event.dataTransfer.setData('sprintTaskId', this.chat.id)
      event.dataTransfer.effectAllowed = 'move'
    },
    onClose() {
      this.containerApi.removePanel(this.panel)
    }
  }
}
</script>
